struct CHSV32 {
  union { struct { uint16_t h; uint8_t s; uint8_t v; }; uint32_t hsv32; };
  CHSV32() = default;
  CHSV32(uint16_t ih, uint8_t is, uint8_t iv) : h(ih), s(is), v(iv) {}
  CHSV32(uint8_t ih, uint8_t is, uint8_t iv) : h((uint16_t)ih << 8), s(is), v(iv) {}
  CHSV32(const CHSV& c) : h((uint16_t)c.h << 8), s(c.s), v(c.v) {}
  operator CHSV() const { return CHSV((uint8_t)(h >> 8), s, v); }
  inline CHSV32(const CRGBW& rgb);
  inline CHSV32& operator=(const CRGBW& rgb);
};
// hsv <-> rgb (FastLED's rainbow conversion; WLED uses its own 16 bit hue variant, the colours are the same)
static inline void hsv2rgb_rainbow16(uint16_t h, uint8_t s, uint8_t v, uint8_t* raw) {
  CRGB c; hsv2rgb_rainbow(CHSV((uint8_t)(h >> 8), s, v), c);
  raw[0] = c.b; raw[1] = c.g; raw[2] = c.r; raw[3] = 0;     // B, G, R, W
}
struct CRGBW {
  union { uint32_t color32; struct { uint8_t b, g, r, w; }; uint8_t raw[4]; };
  CRGBW() = default;
  constexpr CRGBW(uint32_t color) : color32(color) {}
  constexpr CRGBW(uint8_t red, uint8_t green, uint8_t blue, uint8_t white = 0) : b(blue), g(green), r(red), w(white) {}
  constexpr CRGBW(CRGB rgb) : b(rgb.b), g(rgb.g), r(rgb.r), w(0) {}
  CRGBW(CHSV32 hsv) { hsv2rgb_rainbow16(hsv.h, hsv.s, hsv.v, raw); }
  CRGBW(CHSV hsv) { hsv2rgb_rainbow16((uint16_t)hsv.h << 8, hsv.s, hsv.v, raw); }
  const uint8_t& operator[](uint8_t x) const { return raw[x]; }
  CRGBW& operator=(uint32_t color) { color32 = color; return *this; }
  CRGBW& operator=(CHSV32 hsv) { hsv2rgb_rainbow16(hsv.h, hsv.s, hsv.v, raw); return *this; }
  CRGBW& operator=(CHSV hsv) { hsv2rgb_rainbow16((uint16_t)hsv.h << 8, hsv.s, hsv.v, raw); return *this; }
  CRGBW& operator=(const CRGB& rgb) { b = rgb.b; g = rgb.g; r = rgb.r; w = 0; return *this; }
  operator uint32_t() const { return color32; }
  uint8_t getAverageLight() const { return (r + g + b + w) >> 2; }
  uint8_t getRGBaverage() const { return ((r + g + b) * 21846) >> 16; }
};
static inline void rgb2hsv(const CRGBW& rgb, CHSV32& hsv) {
  CHSV h = rgb2hsv_approximate(CRGB(rgb.r, rgb.g, rgb.b)); hsv.h = (uint16_t)h.h << 8; hsv.s = h.s; hsv.v = h.v;
}
inline CHSV32::CHSV32(const CRGBW& rgb) { rgb2hsv(rgb, *this); }
inline CHSV32& CHSV32::operator=(const CRGBW& rgb) { rgb2hsv(rgb, *this); return *this; }
static inline void hsv2rgb_spectrum(const CHSV32& hsv, CRGBW& rgb) {
  CRGB c; hsv2rgb_spectrum(CHSV((uint8_t)(hsv.h >> 8), hsv.s, hsv.v), c); rgb = c;
}
static inline CHSV rgb2hsv(const CRGB c) { return rgb2hsv_approximate(c); }
static inline CRGBW hsv2rgb(const CHSV32& hsv) { return CRGBW(hsv); }

