  void addPixelColor(int n, uint32_t color, bool preserveCR = true) const { setPixelColor(n, color_add(getPixelColor(n), color, preserveCR)); }
  void addPixelColor(int n, CRGB c, bool preserveCR = true) const { addPixelColor(n, RGBW32(c.r, c.g, c.b, 0), preserveCR); }
  void fadePixelColor(uint16_t n, uint8_t fade) const { setPixelColor((int)n, color_fade(getPixelColor(n), fade, true)); }

