        setPixelColorXY((int)xL, (int)yB, color_blend(col, cXLYB, uint8_t(sqrtf(dL * dB) * 255.0f)));
        setPixelColorXY((int)xR, (int)yB, color_blend(col, cXRYB, uint8_t(sqrtf(dR * dB) * 255.0f)));
